script:
(function () {
  'use strict';
  // Commission on a sales amount, with an optional base pay and commission split.
  //   Flat:            commission = sales x rate
  //   Tiered, marginal: each tier's rate applies only to the sales inside that tier
  //                     (tier k covers sales above limit k-1 up to and including limit k)
  //   Tiered, whole:    the rate of the tier the total sales fall in applies to all sales
  //   Your commission = commission x your share; total pay = base pay + your commission
  //   Sales needed for a target: solved exactly tier by tier (commission is linear inside a tier),
  //     taking the first tier where the target is reached.
  // Verified (Node, scratch tests, hand-checked): $50,000 at 5% -> $2,500.00. Tiers 3% to $20,000,
  //   5% to $50,000, 7% above: marginal $50,000 -> $600 + $1,500 = $2,100.00; $80,000 -> $4,200.00;
  //   whole $50,000 -> 5% x $50,000 = $2,500.00, $80,000 -> $5,600.00. Inverse: marginal target
  //   $4,200 -> $80,000.00; whole target $3,000 -> $50,000.01
  //   (at $50,000 the 5% tier pays $2,500; one cent more moves all sales to 7%); flat 5% target $2,500 -> $50,000.00;
  //   a 50% split doubles the sales needed; a 0% rate makes the target unreachable (no Infinity).
  //   Whole script run under Node with a stub DOM: no NaN/Infinity reaches the page.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var whole = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  // tiers: [{ lo, hi, rate }] in order, last hi = Infinity
  function tierIndex(tiers, s) {
    for (var i = 0; i < tiers.length; i++) if (s <= tiers[i].hi) return i;
    return tiers.length - 1;
  }

  function commission(tiers, method, s) {
    if (s <= 0) return { total: 0, parts: tiers.map(function () { return { sales: 0, amount: 0 }; }) };
    if (method === 'whole') {
      var k = tierIndex(tiers, s);
      return { total: s * tiers[k].rate, parts: tiers.map(function (t, i) {
        return i === k ? { sales: s, amount: s * t.rate } : { sales: 0, amount: 0 };
      }) };
    }
    var total = 0, parts = tiers.map(function (t) {
      var inTier = Math.max(0, Math.min(s, t.hi) - t.lo);
      total += inTier * t.rate;
      return { sales: inTier, amount: inTier * t.rate };
    });
    return { total: total, parts: parts };
  }

  // Smallest sales amount whose commission reaches g (g > 0); null if unreachable.
  function salesNeeded(tiers, method, g) {
    if (g <= 0) return 0;
    var cum = 0;
    for (var i = 0; i < tiers.length; i++) {
      var t = tiers[i];
      if (method === 'whole') {
        if (t.rate > 0) {
          var s = g / t.rate;
          if (s <= t.lo) s = t.lo + 0.01; // just above the tier's floor
          if (s <= t.hi) return s;
        }
      } else {
        var room = (t.hi - t.lo) * t.rate;
        if (t.rate > 0 && cum + room >= g) return t.lo + (g - cum) / t.rate;
        if (isFinite(room)) cum += room;
      }
    }
    return null;
  }

  function readNum(id, blankValue) {
    var el = document.getElementById(id);
    if (!el) return NaN;
    if (el.value === '' && blankValue !== undefined) return blankValue;
    var v = parseFloat(el.value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }
  function show(id, on) { var el = document.getElementById(id); if (el) el.hidden = !on; }
  function rateText(r) { return (Math.round(r * 100000) / 1000).toString() + '%'; }

  function readTiers() {
    var tiers = [], lo = 0;
    for (var i = 1; i <= 4; i++) {
      var rate = readNum('cmRate' + i);
      var hi = i < 4 ? readNum('cmLimit' + i, Infinity) : Infinity;
      if (!isFinite(rate) || rate < 0 || rate > 100) return { error: 'Enter a rate from 0 to 100% for tier ' + i + '.' };
      if (isNaN(hi) || hi <= lo) return { error: 'Each tier limit must be higher than the one before it (tier ' + i + ').' };
      tiers.push({ lo: lo, hi: hi, rate: rate / 100 });
      if (!isFinite(hi)) break;
      lo = hi;
    }
    return { tiers: tiers };
  }

  function fillTable(rows) {
    var body = document.getElementById('cmTiers');
    if (!body) return;
    while (body.firstChild) body.removeChild(body.firstChild);
    rows.forEach(function (cells) {
      var tr = document.createElement('tr');
      cells.forEach(function (t) {
        var td = document.createElement('td');
        td.textContent = t;
        tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  function clear() {
    ['cmResult', 'cmTotalPay', 'cmEffective', 'cmGross', 'cmNeeded'].forEach(function (id) { set(id, '–'); });
    fillTable([]);
  }

  function update() {
    var typeEl = document.getElementById('cmType');
    var type = typeEl && typeEl.value === 'tiered' ? 'tiered' : 'flat';
    var methodEl = document.getElementById('cmMethod');
    var method = methodEl && methodEl.value === 'whole' ? 'whole' : 'marginal';
    show('cmFlatFields', type === 'flat');
    show('cmTierFields', type === 'tiered');
    show('cmTierSection', type === 'tiered');

    var sales = readNum('cmSales'), base = readNum('cmBase', 0), share = readNum('cmShare', 100), target = readNum('cmTarget', 0);
    var msg = '', tiers;
    if (!isFinite(sales) || sales < 0 || sales > 1e12) msg = 'Enter a sales amount of 0 or more.';
    else if (!isFinite(base) || base < 0 || !isFinite(target) || target < 0 || base > 1e12 || target > 1e12) msg = 'Enter base pay and target earnings of 0 or more.';
    else if (!isFinite(share) || share < 0 || share > 100) msg = 'Enter your share of the commission from 0 to 100%.';
    if (!msg) {
      if (type === 'flat') {
        var rate = readNum('cmRate');
        if (!isFinite(rate) || rate < 0 || rate > 100) msg = 'Enter a commission rate from 0 to 100%.';
        else tiers = [{ lo: 0, hi: Infinity, rate: rate / 100 }];
      } else {
        var t = readTiers();
        if (t.error) msg = t.error; else tiers = t.tiers;
      }
    }
    var error = document.getElementById('cmError');
    if (error) { error.hidden = !msg; error.textContent = msg; }
    if (msg) { clear(); return; }

    var c = commission(tiers, type === 'flat' ? 'marginal' : method, sales);
    var yours = c.total * share / 100;
    set('cmResult', money.format(yours));
    set('cmTotalPay', money.format(base + yours));
    set('cmGross', money.format(c.total));
    set('cmEffective', sales > 0 ? rateText(yours / sales) : '0%');

    var neededCommission = target - base;
    if (target <= 0) set('cmNeeded', 'Enter a target');
    else if (neededCommission <= 0) set('cmNeeded', money.format(0) + ' (base pay covers it)');
    else if (share <= 0) set('cmNeeded', 'Not reachable');
    else {
      var s = salesNeeded(tiers, type === 'flat' ? 'marginal' : method, neededCommission / (share / 100));
      set('cmNeeded', s === null ? 'Not reachable at these rates' : money.format(Math.ceil(s * 100 - 1e-6) / 100));
    }

    fillTable(type === 'tiered' ? tiers.map(function (t, i) {
      var range = isFinite(t.hi) ? whole.format(t.lo) + ' – ' + whole.format(t.hi) : 'Over ' + whole.format(t.lo);
      return ['Tier ' + (i + 1), range, rateText(t.rate), money.format(c.parts[i].sales), money.format(c.parts[i].amount)];
    }) : []);
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('cmForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
